class ShoppingCart:
    def __init__(self):
        self.items = []

    def add_item(self, name: str, qty: int, price: float):
        for item in self.items:
            if item['name'] == name:
                item['qty'] += qty
                return
        self.items.append({'name': name, 'qty': qty, 'price': price})
```

